#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void bmm_kernel(
    const half* __restrict__ A,
    const half* __restrict__ B,
    half* __restrict__ C,
    int batch_size,
    int m,
    int k,
    int n
) {
    int batch_idx = blockIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.z * blockDim.z + threadIdx.z;

    if (batch_idx >= batch_size || row >= m || col >= n) return;

    float sum = 0.0f;
    const half* a_row = A + batch_idx * m * k + row * k;
    const half* b_col = B + batch_idx * k * n + col;

    for (int i = 0; i < k; ++i) {
        sum += static_cast<float>(a_row[i]) * static_cast<float>(b_col[i * n]);
    }

    C[batch_idx * m * n + row * n + col] = __float2half(sum);
}

